    $('todayStart').onclick=async ()=>{ $('todayOverlay').classList.remove('on'); await tripAction(t.id,'start'); };
    $('todayResched').onclick=()=>{ $('todayOverlay').classList.remove('on'); openReschedModal(t.id); };
    $('todayOverlay').classList.add('on');
